          "description": "Answers questions about company policies and procedures, troubleshooting steps, or product information. For example: “What is your return policy?” “How do I fix an issue?” or “What features does a product have?”"
        },
        {
          "name": "Cancel Order",
          "apiName": "CancelOrder_179Ru000000PPo4",
          "description": "Cancels a customer’s order."
        },
        {
          "name": "Finalize New Delivery Time",
          "apiName": "FinalizeNewDeliveryTime_179Ru000000PPo4",
          "description": "Updates the scheduled delivery time to the time slot selected by the customer."
        },
        {
          "name": "Get Delivery Time Slots",
          "apiName": "GetDeliveryTimeSlots_179Ru000000PPo4",
          "description": "Returns a list of available time slots to schedule a delivery."
        },
        {
          "name": "Get Orders By Contact",
          "apiName": "GetOrdersByContact_179Ru000000PPo4",
          "description": "Returns a list of orders associated with a given contact record."
