      "name": "Reservation Management",
      "apiName": "ReservationManagement_16jRu000000VWhx",
      "description": "Handles requests to create new reservations for customers at their desired time slots.",
      "actions": [
        {
          "name": "Answer Questions with Knowledge",
          "apiName": "AnswerQuestionsWithKnowledge_179Ru000000PPo1",
          "description": "Answers questions about company policies and procedures, troubleshooting steps, or product information. For example: “What is your return policy?” “How do I fix an issue?” or “What features does a product have?”"
        },
        {
          "name": "Finalize Reservation",
          "apiName": "FinalizeReservation_179Ru000000PPo1",
          "description": "Books and finalizes a reservation for the time designated by the customer."
        },
        {
          "name": "Get Reservation Time Slots",
          "apiName": "GetReservationTimeSlots_179Ru000000PPo1",
          "description": "Returns a list of available time slots for the date specified by the customer."
        },
        {
          "name": "Identify Customer By Email",
          "apiName": "IdentifyCustomerByEmail_179Ru000000PPo1",
          "description": "Identify a customer by their email address and return their contact record."
        }
      ]
    },
    {
      "name": "Service Customer Verification",
      "apiName": "ServiceCustomerVerification_16jRu000000VWhx",
      "description": "Verifies the customer's identity before granting access to sensitive data. Actions like managing cases, retrieving/managing orders, or making a reservation require identity verification. Sensitive data includes confidential, private, or security-protected information, such as business-critical data or personally identifiable information (PII). After verification is successful, don't repeat the process within the same session.",
      "actions": [
        {
          "name": "Send Email with Verification Code",
          "apiName": "SendEmailVerificationCode_179Ru000000PPo7",
          "description": "Sends a generated verification code to the user’s email address."
        },
        {
          "name": "Verify Customer",
          "apiName": "VerifyCustomer_179Ru000000PPo7",
          "description": "Verifies whether the verification code entered by the user matches the code sent to the user's email address."
        }
      ]
    }
  ],
  "unassignedActions": [
